record.field:
result = 0
if not employee.rap_excluded:
    version = employee.current_version_id
    if version:
        # Check include_in: skip period if not applicable
        apply = True
        rap_config = version.rap_setup_id
        if rap_config and rap_config.include_in and payslip.date_from:
            day = payslip.date_from.day
            if rap_config.include_in == 'first' and day > 15:
                apply = False
            elif rap_config.include_in == 'second' and day <= 15:
                apply = False
        if apply:
            if version.rap_manual:
                result = -round(abs(version.amount_rap_manual), 2)
            elif version.rap_fee:
                result = -round(abs(version.rap_fee), 2)
            elif version.rap_foviif_amount_monthly:
                result = -round(abs(version.rap_foviif_amount_monthly), 2)

result = 0
year = (payslip.date_to or payslip.date_from).year if (payslip.date_to or payslip.date_from) else 2020
settings = payslip.env['l10n.hn.vecinal.settings'].search([
    ('year_apply', '=', year),
    ('company_id', '=', payslip.company_id.id),
    ('active', '=', True)
], limit=1)
if settings:
    # Get employee income for base year
    income_record = payslip.env['l10n.hn.vecinal.employee_income'].search([
        ('employee_id', '=', employee.id),
        ('year_base', '=', settings.income_year_base),
        ('company_id', '=', payslip.company_id.id),
        ('state', '=', 'confirmed')
    ], limit=1)
    if income_record and income_record.annual_income > 0:
        # Calculate annual tax
        annual_tax = settings.calculate_annual_tax(income_record.annual_income)
        # Use the new method to get period amount based on deduction method
        # For monthly payslips with quincena-based deduction, use helper (no date import in rule)
        if settings.deduction_method in ['first_quincena_january', 'first_two_quincenas_january', 'first_four_quincenas', 'biweekly_all_year']:
            if payslip.date_from and payslip.date_to:
                result = settings.get_period_amount_for_month(annual_tax, payslip.date_from.year, payslip.date_from.month)
            else:
                result = settings.get_period_amount(annual_tax, payslip.date_from, payslip.date_to)
        else:
            result = settings.get_period_amount(annual_tax, payslip.date_from, payslip.date_to)
        # Create history record
        if result != 0:
            payslip.env['l10n.hn.vecinal.retention_history'].create_from_payslip(
                payslip, income_record.annual_income, annual_tax, result, settings
            )
    else:
        # No income record or zero income
        result = 0

# Días sin goce = líneas con work_entry_type en unpaid_work_entry_type_ids
unpaid_days = 0.0
struct = payslip.struct_id
if struct and struct.use_worked_day_lines and struct.unpaid_work_entry_type_ids:
    unpaid_ids = struct.unpaid_work_entry_type_ids.ids
    for wd in (worked_days or {}).values():
        if not wd:
            continue
        wet = wd.work_entry_type_id
        if wet and wet.id in unpaid_ids:
            unpaid_days += abs(wd.number_of_days or 0)
result = unpaid_days > 0
